mapper.select:
select vw.id, vw.create_user_id, vw.create_user_name, vw.create_time, vw.update_user_id, vw.update_user_name, vw.update_time, vw.disabled, vw.code, vw.name from virtual_warehouse vw where ${params.sqlMap.default} and vw.is_deleted=false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
vw.id desc

SELECT id, name,code,disabled FROM virtual_warehouse WHERE is_deleted=false
and name in
#{name}

select vw.id, vw.code, vw.name, vwr.warehouse_id, wh.name as warehouseName, vw.disabled, vwc.dict_platform, vwc.relation_id as shopId, vwcpr.partition_id, vw.create_user_name, vw.create_time, vw.update_user_name, vw.update_time from virtual_warehouse vw left join virtual_warehouse_channel vwc on vw.id = vwc.virtual_warehouse_id and vwc.is_deleted = false left join virtual_warehouse_channel_partition_ref vwcpr on vwc.id = vwcpr.main_id and vwcpr.is_deleted = false left join virtual_warehouse_relation vwr on vw.id = vwr.virtual_warehouse_id and vwr.is_deleted = false left join warehouse wh on vwr.warehouse_id = wh.id and wh.is_deleted = false where ${params.sqlMap.default} and vw.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
vw.id desc

SELECT vw.id as virtualWarehouseId, vw.name as virtualWarehouseName, w.id as warehouseId, w."name" as warehouseName FROM virtual_warehouse vw LEFT JOIN virtual_warehouse_relation vwr on vwr.virtual_warehouse_id = vw.id and vwr.is_deleted = false and vwr.disabled = false LEFT JOIN warehouse w on vwr.warehouse_id = w.id and w.is_deleted = false
and vw.id in
#{item}
